import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const root = process.env.MIGRATION_PROJECT;
const {serialize} = await import(pathToFileURL(root + '/producer.mjs'));
const {deserialize} = await import(pathToFileURL(root + '/consumer.mjs'));
const rows = [{id:'b',title:'서명 📝',archived:true},{id:'a',title:'é文'}];
const before = structuredClone(rows);
const wire = serialize(rows);
assert.deepEqual(rows, before);
assert.deepEqual(JSON.parse(wire).entries.map(row => row.title), ['서명 📝','é文']);
assert.deepEqual(deserialize(wire).map(row => row.title), ['서명 📝','é文']);
assert.deepEqual(deserialize(JSON.stringify({version:1,items:[{id:'b',title:'서명 📝'}]})), [{id:'b',title:'서명 📝',archived:false}]);
console.log('PASS: Unicode preserved across current and legacy boundaries; caller rows unchanged.');
